# frozen_string_literal: true

require "bridgetown-feed/generator"

# Use the site's feed template for all feeds generated by bridgetown-feed.
module Builders
  class FeedTemplateBuilder < SiteBuilder
    module SiteFeedTemplate
      private

      def feed_source_path
        File.expand_path("../feed.liquid", __dir__)
      end
    end

    def build
      BridgetownFeed::Generator.prepend(SiteFeedTemplate)
    end
  end
end
